import json
from pathlib import Path

def collect_files(root: Path) -> list[dict]:
    if not root.is_dir():
        raise NotADirectoryError(f"Нет каталога: {root}")
    rows = [
        {"name": item.name, "size_bytes": item.stat().st_size}
        for item in root.iterdir()
        if item.is_file()
    ]
    return sorted(rows, key=lambda row: row["name"])

def main() -> int:
    root = Path("data")
    target = Path("report.json")
    temporary = Path("report.json.tmp")
    try:
        rows = collect_files(root)
        temporary.write_text(
            json.dumps(rows, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )
        temporary.replace(target)
    except (OSError, ValueError) as exc:
        print(f"ERROR: {exc}")
        return 1
    print(f"OK: {len(rows)} files")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())

import time
import requests

def fetch_health(url: str, attempts: int = 3) -> str:
    last_error: Exception | None = None
    for attempt in range(1, attempts + 1):
        try:
            response = requests.get(url, timeout=(3, 10))
            response.raise_for_status()
            payload = response.json()
            status = payload.get("status")
            if not isinstance(status, str):
                raise ValueError("В JSON нет строкового поля status")
            return status
        except (requests.Timeout, requests.ConnectionError) as exc:
            last_error = exc
            if attempt < attempts:
                time.sleep(attempt)
    raise RuntimeError(f"API недоступен после {attempts} попыток") from last_error

