import argparse
import json
import logging
from pathlib import Path

def load_config(path: Path) -> dict:
    return json.loads(path.read_text(encoding="utf-8"))

def validate_config(data: dict) -> list[str]:
    errors: list[str] = []
    name = data.get("name")
    port = data.get("port")
    replicas = data.get("replicas")
    health_url = data.get("health_url")
    if not isinstance(name, str) or not name.strip():
        errors.append("name должен быть непустой строкой")
    if not isinstance(port, int) or not 1 <= port <= 65535:
        errors.append("port должен быть числом от 1 до 65535")
    if not isinstance(replicas, int) or not 1 <= replicas <= 50:
        errors.append("replicas должен быть числом от 1 до 50")
    if not isinstance(health_url, str) or not health_url.startswith(("http://", "https://")):
        errors.append("health_url должен начинаться с http:// или https://")
    return errors

def main() -> int:
    parser = argparse.ArgumentParser(description="Проверка конфига сервиса")
    parser.add_argument("path", type=Path)
    parser.add_argument("--verbose", action="store_true")
    args = parser.parse_args()
    logging.basicConfig(level=logging.DEBUG if args.verbose else logging.INFO)
    try:
        data = load_config(args.path)
    except (OSError, json.JSONDecodeError) as exc:
        logging.error("Не удалось прочитать конфиг: %s", exc)
        return 1
    errors = validate_config(data)
    if errors:
        for error in errors:
            print(f"ERROR: {error}")
        return 2
    print(f"OK: {data['name']}")
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
